-- Part 2 — hand-written objects (ADR-019)
-- ===================================================================================================

-- app_user
ALTER TABLE "app_user" ADD CONSTRAINT "app_user_failed_login_count_check" CHECK (failed_login_count >= 0);
ALTER TABLE "app_user" ADD CONSTRAINT "app_user_deactivation_reason_check" CHECK (is_active OR deactivation_reason IS NOT NULL);

-- session: selected membership is all-or-nothing; partial indexes for live sessions
ALTER TABLE "session" ADD CONSTRAINT "session_selection_pair_check" CHECK ((active_clinic_id IS NULL) = (active_member_id IS NULL));
CREATE INDEX "session_user_live_idx" ON "session" ("user_id") WHERE revoked_at IS NULL;
CREATE INDEX "session_active_member_live_idx" ON "session" ("active_member_id") WHERE revoked_at IS NULL;

-- clinic (BR-010 slug, FR-CLN-005/006 settings ranges, FR-PLT-003 suspend reason)
ALTER TABLE "clinic" ADD CONSTRAINT "clinic_slug_check" CHECK (
  length(slug) BETWEEN 3 AND 40
  AND slug::text ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
  AND slug::text NOT IN ('admin', 'api', 'app', 'c', 'login', 'static', 'www'));
ALTER TABLE "clinic" ADD CONSTRAINT "clinic_phone_region_check" CHECK (default_phone_region ~ '^[A-Z]{2}$');
ALTER TABLE "clinic" ADD CONSTRAINT "clinic_settings_check" CHECK (
  slot_granularity_min IN (5, 10, 15, 20, 30, 60)
  AND hold_minutes BETWEEN 5 AND 30
  AND min_notice_min BETWEEN 0 AND 1440
  AND horizon_days BETWEEN 1 AND 90
  AND cancel_cutoff_min BETWEEN 0 AND 2880
  AND checkin_before_min >= 0 AND checkin_after_min >= 0 AND no_show_grace_min >= 0
  AND max_active_bookings >= 1
  AND (walkin_daily_capacity IS NULL OR walkin_daily_capacity BETWEEN 1 AND 500)
  AND walkin_closes_before_min >= 0);
ALTER TABLE "clinic" ADD CONSTRAINT "clinic_walkin_capacity_check" CHECK (NOT walkin_enabled OR walkin_daily_capacity IS NOT NULL);
ALTER TABLE "clinic" ADD CONSTRAINT "clinic_suspend_reason_check" CHECK (status <> 'SUSPENDED' OR status_reason IS NOT NULL);

-- FR-CLN-002 / A-017: slug and time zone are immutable once the clinic has been activated.
CREATE FUNCTION clinic_lock_after_activation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.activated_at IS NOT NULL AND (NEW.slug IS DISTINCT FROM OLD.slug OR NEW.timezone IS DISTINCT FROM OLD.timezone) THEN
    RAISE EXCEPTION 'clinic slug and timezone are immutable after activation' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER "clinic_lock_after_activation" BEFORE UPDATE OF slug, timezone ON "clinic"
  FOR EACH ROW EXECUTE FUNCTION clinic_lock_after_activation();

-- clinic_member
ALTER TABLE "clinic_member" ADD CONSTRAINT "clinic_member_roles_check" CHECK (cardinality(roles) >= 1);

-- clinic_business_hour (BR-040/041): same-day intervals, no overlap per weekday
ALTER TABLE "clinic_business_hour" ADD CONSTRAINT "clinic_business_hour_range_check" CHECK (
  weekday BETWEEN 1 AND 7 AND start_min BETWEEN 0 AND 1439 AND end_min BETWEEN 1 AND 1440 AND start_min < end_min);
ALTER TABLE "clinic_business_hour" ADD CONSTRAINT "clinic_business_hour_no_overlap"
  EXCLUDE USING gist (clinic_id WITH =, weekday WITH =, int4range(start_min, end_min) WITH &&);

-- clinic_closure (FR-CLN-004)
ALTER TABLE "clinic_closure" ADD CONSTRAINT "clinic_closure_range_check" CHECK (
  end_date >= start_date
  AND ((start_min IS NULL AND end_min IS NULL)
       OR (start_min IS NOT NULL AND end_min IS NOT NULL AND start_date = end_date
           AND start_min BETWEEN 0 AND 1439 AND end_min BETWEEN 1 AND 1440 AND start_min < end_min)));

-- clinic_service (FR-SVC-001)
ALTER TABLE "clinic_service" ADD CONSTRAINT "clinic_service_duration_check" CHECK (duration_min BETWEEN 5 AND 240 AND duration_min % 5 = 0);
ALTER TABLE "clinic_service" ADD CONSTRAINT "clinic_service_name_check" CHECK (length(name) >= 2);

-- doctor_availability (BR-045)
ALTER TABLE "doctor_availability" ADD CONSTRAINT "doctor_availability_range_check" CHECK (
  weekday BETWEEN 1 AND 7 AND start_min BETWEEN 0 AND 1439 AND end_min BETWEEN 1 AND 1440 AND start_min < end_min);
ALTER TABLE "doctor_availability" ADD CONSTRAINT "doctor_availability_no_overlap"
  EXCLUDE USING gist (doctor_id WITH =, weekday WITH =, int4range(start_min, end_min) WITH &&);

-- schedule_exception (BR-046)
ALTER TABLE "schedule_exception" ADD CONSTRAINT "schedule_exception_range_check" CHECK (
  ((start_min IS NULL AND end_min IS NULL)
   OR (start_min IS NOT NULL AND end_min IS NOT NULL AND start_min BETWEEN 0 AND 1439 AND end_min BETWEEN 1 AND 1440 AND start_min < end_min))
  AND (kind <> 'MODIFIED_HOURS' OR start_min IS NOT NULL));
ALTER TABLE "schedule_exception" ADD CONSTRAINT "schedule_exception_modified_no_overlap"
  EXCLUDE USING gist (doctor_id WITH =, exception_date WITH =, int4range(start_min, end_min) WITH &&) WHERE (kind = 'MODIFIED_HOURS');

-- Privileges: the application role may read/write tenant data; audit_log is append-only (FR-AUD-003).
GRANT SELECT, INSERT, UPDATE, DELETE ON
  "app_user", "session", "clinic", "clinic_member", "doctor", "clinic_business_hour", "clinic_closure",
  "clinic_service", "doctor_service", "doctor_availability", "schedule_exception" TO sc_app;
GRANT SELECT, INSERT ON "audit_log" TO sc_app;
REVOKE UPDATE, DELETE, TRUNCATE ON "audit_log" FROM sc_app;
GRANT USAGE, SELECT ON SEQUENCE "audit_log_id_seq" TO sc_app;
GRANT ALL ON ALL TABLES IN SCHEMA public TO sc_owner;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO sc_owner;
